package com.obddroid.ui.activities;

import java.util.HashMap;
import java.util.Map;

/** Türkçe arıza açıklamaları (genel bilgi; marka servis verisi değildir). */
final class TurkishDtc {
    private static final Map<String, String> MAP = new HashMap<>();
    static {
        MAP.put("P0401", "EGR akışı yetersiz\n\nNe anlama geliyor?\nEmme tarafına dönen egzoz gazı beklenenden az algılanıyor.\n\nOlası nedenler\n• EGR valfinde kurum veya takılma\n• EGR kanalında tıkanıklık\n• Sensör, kablo veya hortum sorunu\n\nKontrol adımları\n1. Soket ve hortumları kontrol edin\n2. EGR valfi ve kanallarını kontrol ettirin\n\nDikkat\nMotor lambası yanıyorsa aracı kısa sürede kontrol ettirin.");
        MAP.put("P0402", "EGR akışı fazla\n\nNe anlama geliyor?\nEmme tarafına dönen egzoz gazı beklenenden fazla algılanıyor.\n\nOlası nedenler\n• EGR valfinin açık takılı kalması\n• Sensör veya kontrol arızası\n\nKontrol adımları\n1. EGR konum ve hava akışı verilerini kontrol ettirin\n\nDikkat\nMotor lambası yanıyorsa aracı kısa sürede kontrol ettirin.");
        MAP.put("P0101", "Hava akış (MAF) sinyali aralık dışı\n\nNe anlama geliyor?\nÖlçülen hava miktarı beklenen değerle uyuşmuyor.\n\nOlası nedenler\n• Emiş kaçağı\n• Tıkalı hava filtresi\n• Kirli veya arızalı MAF, kablo sorunu\n\nKontrol adımları\n1. Hava filtresi ve emiş hortumlarını kontrol edin\n2. MAF soketini ve canlı verisini kontrol ettirin\n\nDikkat\nMotor lambası yanıyorsa aracı kısa sürede kontrol ettirin.");
        MAP.put("P0113", "Emme havası sıcaklık sinyali yüksek\n\nNe anlama geliyor?\nSensör devresinden aşırı yüksek sinyal geliyor.\n\nOlası nedenler\n• Açık devre veya gevşek soket\n• Arızalı sensör\n\nKontrol adımları\n1. Soket ve kabloyu kontrol edin\n2. Sensör değerini dış sıcaklıkla karşılaştırın (motor soğukken)\n\nDikkat\nMotor lambası yanıyorsa aracı kısa sürede kontrol ettirin.");
        MAP.put("P0117", "Soğutma suyu sensörü sinyali düşük\n\nNe anlama geliyor?\nSıcaklık sensörü devresinden düşük sinyal geliyor.\n\nOlası nedenler\n• Kısa devre\n• Arızalı sensör\n\nKontrol adımları\n1. Soket ve kabloyu kontrol edin\n\nDikkat\nHararet uyarısı varsa güvenli yerde durup motoru kapatın. Sıcakken radyatör kapağını açmayın.");
        MAP.put("P0118", "Soğutma suyu sensörü sinyali yüksek\n\nNe anlama geliyor?\nSıcaklık sensörü devresinden yüksek sinyal geliyor.\n\nOlası nedenler\n• Açık devre veya gevşek soket\n• Arızalı sensör\n\nKontrol adımları\n1. Soket ve kabloyu kontrol edin\n\nDikkat\nHararet uyarısı varsa güvenli yerde durup motoru kapatın. Sıcakken radyatör kapağını açmayın.");
        MAP.put("P0128", "Motor çalışma sıcaklığına ulaşmıyor\n\nNe anlama geliyor?\nSoğutma suyu beklenen sürede yeterince ısınmıyor.\n\nOlası nedenler\n• Termostatın açık kalması\n• Sıcaklık sensörü veya soğutma suyu seviyesi sorunu\n\nKontrol adımları\n1. Motor soğukken su seviyesini kontrol edin\n2. Termostat ve sensörü kontrol ettirin\n\nDikkat\nHararet uyarısı varsa güvenli yerde durup motoru kapatın. Sıcakken radyatör kapağını açmayın.");
        MAP.put("P0087", "Yakıt rayı basıncı çok düşük\n\nNe anlama geliyor?\nYakıt sistemi basıncı istenen değerin altında.\n\nOlası nedenler\n• Yakıt filtresi veya besleme sorunu\n• Pompa, enjektör, sensör arızası veya kaçak\n\nKontrol adımları\n1. Gözle görülür kaçak ve yakıt filtresini kontrol edin\n2. Yüksek basınç sistemini yalnızca ustaya kontrol ettirin\n\nDikkat\nYakıt kaçağı veya kokusu varsa aracı çalıştırmayın. Yüksek basınç hatlarını gevşetmeyin.");
        MAP.put("P0299", "Turbo basıncı düşük\n\nNe anlama geliyor?\nTurbo veya süperşarj basıncı beklenenden az.\n\nOlası nedenler\n• Basınç hortumu veya intercooler kaçağı\n• Turbo kontrol sistemi veya turbo sorunu\n• Sensör arızası\n\nKontrol adımları\n1. Hortum ve kelepçeleri kontrol edin\n2. İstenen ve ölçülen basıncı karşılaştırtın\n\nDikkat\nGüç kaybı, anormal ses veya yoğun duman varsa aracı zorlamayın.");
        MAP.put("P0234", "Turbo basıncı aşırı\n\nNe anlama geliyor?\nTurbo basıncı beklenen sınırı aşıyor.\n\nOlası nedenler\n• Turbo kontrol mekanizması veya valfi\n• Basınç sensörü sorunu\n\nKontrol adımları\n1. Turbo kontrol sistemini ve verileri kontrol ettirin\n\nDikkat\nAracı zorlamayın, kısa sürede servise başvurun.");
        MAP.put("P0300", "Rastgele / çoklu silindirde tekleme\n\nNe anlama geliyor?\nBirden fazla veya değişen silindirlerde düzensiz yanma algılanıyor.\n\nOlası nedenler\n• Yakıt sistemi veya enjektör\n• Düşük kompresyon\n• Hava veya EGR sistemi\n• Benzinli motorda buji veya bobin\n\nKontrol adımları\n1. Diğer kodlara bakın\n2. Enjektör ve kompresyonu kontrol ettirin\n\nDikkat\nMotor lambası yanıp sönüyor veya motor sarsılıyorsa güvenli yerde durup destek alın.");
        MAP.put("P0301", "1. silindirde tekleme\n\nNe anlama geliyor?\n1. silindirde düzensiz yanma algılanıyor.\n\nOlası nedenler\n• Enjektör veya kablosu\n• Düşük kompresyon\n• Benzinli motorda buji veya bobin\n\nKontrol adımları\n1. İlgili silindirin enjektörünü ve kompresyonunu kontrol ettirin\n\nDikkat\nMotor lambası yanıp sönüyor veya motor sarsılıyorsa güvenli yerde durup destek alın.");
        MAP.put("P0302", "2. silindirde tekleme\n\nNe anlama geliyor?\n2. silindirde düzensiz yanma algılanıyor.\n\nOlası nedenler\n• Enjektör veya kablosu\n• Düşük kompresyon\n• Benzinli motorda buji veya bobin\n\nKontrol adımları\n1. İlgili silindirin enjektörünü ve kompresyonunu kontrol ettirin\n\nDikkat\nMotor lambası yanıp sönüyor veya motor sarsılıyorsa güvenli yerde durup destek alın.");
        MAP.put("P0303", "3. silindirde tekleme\n\nNe anlama geliyor?\n3. silindirde düzensiz yanma algılanıyor.\n\nOlası nedenler\n• Enjektör veya kablosu\n• Düşük kompresyon\n• Benzinli motorda buji veya bobin\n\nKontrol adımları\n1. İlgili silindirin enjektörünü ve kompresyonunu kontrol ettirin\n\nDikkat\nMotor lambası yanıp sönüyor veya motor sarsılıyorsa güvenli yerde durup destek alın.");
        MAP.put("P0304", "4. silindirde tekleme\n\nNe anlama geliyor?\n4. silindirde düzensiz yanma algılanıyor.\n\nOlası nedenler\n• Enjektör veya kablosu\n• Düşük kompresyon\n• Benzinli motorda buji veya bobin\n\nKontrol adımları\n1. İlgili silindirin enjektörünü ve kompresyonunu kontrol ettirin\n\nDikkat\nMotor lambası yanıp sönüyor veya motor sarsılıyorsa güvenli yerde durup destek alın.");
        MAP.put("P0335", "Krank konum sensörü devresi\n\nNe anlama geliyor?\nKrank mili sensör sinyali hatalı.\n\nOlası nedenler\n• Sensör, soket veya kablo\n• Tetik dişlisi sorunu\n\nKontrol adımları\n1. Soket ve kabloyu kontrol edin\n\nDikkat\nMotor stop ediyorsa aracı kullanmayın.");
        MAP.put("P0340", "Eksantrik konum sensörü devresi\n\nNe anlama geliyor?\nEksantrik mili sensör sinyali hatalı.\n\nOlası nedenler\n• Sensör, soket veya kablo\n• Zamanlama sorunu\n\nKontrol adımları\n1. Soket ve kabloyu, gerekirse zamanlamayı kontrol ettirin\n\nDikkat\nMotor stop ediyorsa veya anormal ses varsa aracı kullanmayın.");
        MAP.put("P0380", "Kızdırma bujisi devresi A\n\nNe anlama geliyor?\nKızdırma sistemi devresinde arıza algılanıyor.\n\nOlası nedenler\n• Kızdırma bujisi\n• Röle, sigorta, kablo veya kontrol ünitesi\n\nKontrol adımları\n1. Sigorta ve bağlantıları kontrol edin\n2. Bujileri ve röleyi ölçtürün\n\nDikkat\nMotor lambası yanıyorsa aracı kısa sürede kontrol ettirin.");
        MAP.put("P0420", "Katalizör verimi düşük\n\nNe anlama geliyor?\nKatalizörün çalışması beklenen verimin altında algılanıyor.\n\nOlası nedenler\n• Egzoz kaçağı\n• Oksijen sensörü sorunu\n• Tekleme veya karışım arızası\n• Yıpranmış katalizör\n\nKontrol adımları\n1. Önce diğer motor arızalarını giderin\n2. Egzoz kaçağı ve sensör verilerini kontrol ettirin\n\nDikkat\nMotor lambası yanıyorsa aracı kısa sürede kontrol ettirin.");
        MAP.put("P0500", "Araç hız sensörü arızası\n\nNe anlama geliyor?\nAraç hız bilgisi alınamıyor veya hatalı.\n\nOlası nedenler\n• Hız sensörü veya kablosu\n• ABS sistemiyle ilgili sorun\n\nKontrol adımları\n1. ABS uyarı lambasını ve bağlantıları kontrol edin\n\nDikkat\nABS veya fren uyarısı varsa aracı kontrol ettirmeden kullanmaktan kaçının.");
        MAP.put("P0562", "Sistem voltajı düşük\n\nNe anlama geliyor?\nKontrol ünitesi besleme voltajını düşük algılıyor.\n\nOlası nedenler\n• Zayıf akü\n• Şarj sistemi arızası\n• Oksitli bağlantı veya şasi sorunu\n\nKontrol adımları\n1. Kutup başlarını ve şaseyi kontrol edin\n2. Akü ve şarj voltajını ölçtürün\n\nDikkat\nAkü lambası yanıyorsa araç yolda kalabilir.");
        MAP.put("P0563", "Sistem voltajı yüksek\n\nNe anlama geliyor?\nKontrol ünitesi besleme voltajını yüksek algılıyor.\n\nOlası nedenler\n• Şarj regülatörü\n• Yanlış takviye veya bağlantı sorunu\n\nKontrol adımları\n1. Şarj voltajını ölçtürün\n\nDikkat\nYanık kokusu veya aküde şişme varsa motoru kapatın ve destek alın.");
        MAP.put("P2002", "Partikül filtresi (DPF) verimi düşük\n\nNe anlama geliyor?\nDizel partikül filtresi beklenen verimde algılanmıyor.\n\nOlası nedenler\n• Hasarlı veya sorunlu DPF\n• Basınç sensörü veya hortumu\n• Egzoz kaçağı\n\nKontrol adımları\n1. Egzoz kaçağını ve sensör hortumlarını kontrol ettirin\n2. Kurum yükünü ölçtürün\n\nDikkat\nDPF uyarısı veya güç kaybı varsa servise başvurun. Kodu silmek filtreyi temizlemez.");
        MAP.put("P242F", "DPF kül birikimi tıkanıklığı\n\nNe anlama geliyor?\nFiltrede kül birikimine bağlı kısıtlama algılanıyor.\n\nOlası nedenler\n• Uzun kullanımda kül birikimi\n\nKontrol adımları\n1. DPF durumunu serviste ölçtürün\n2. Rejenerasyon külü temizlemez\n\nDikkat\nDPF uyarısı veya güç kaybı varsa servise başvurun. Kodu silmek filtreyi temizlemez.");
        MAP.put("P244A", "DPF basınç farkı çok düşük\n\nNe anlama geliyor?\nFiltre giriş-çıkış basınç farkı beklenenden düşük.\n\nOlası nedenler\n• Sensör veya hortum sorunu\n• Kaçak veya hasarlı filtre\n\nKontrol adımları\n1. Hortum ve sensörü kontrol ettirin\n\nDikkat\nDPF uyarısı veya güç kaybı varsa servise başvurun. Kodu silmek filtreyi temizlemez.");
        MAP.put("P2452", "DPF basınç sensörü devresi\n\nNe anlama geliyor?\nBasınç sensörü devresinde arıza.\n\nOlası nedenler\n• Sensör, soket veya kablo\n• Tıkalı, delik veya çıkmış hortum\n\nKontrol adımları\n1. Soket, kablo ve hortumları kontrol ettirin\n\nDikkat\nDPF uyarısı veya güç kaybı varsa servise başvurun. Kodu silmek filtreyi temizlemez.");
        MAP.put("P2453", "DPF basınç sensörü aralık dışı\n\nNe anlama geliyor?\nBasınç sensörü sinyali beklenen aralıkta değil.\n\nOlası nedenler\n• Sensör, soket veya kablo\n• Tıkalı, delik veya çıkmış hortum\n\nKontrol adımları\n1. Soket, kablo ve hortumları kontrol ettirin\n\nDikkat\nDPF uyarısı veya güç kaybı varsa servise başvurun. Kodu silmek filtreyi temizlemez.");
        MAP.put("P2454", "DPF basınç sensörü sinyali düşük\n\nNe anlama geliyor?\nBasınç sensöründen düşük sinyal geliyor.\n\nOlası nedenler\n• Sensör, soket veya kablo\n• Tıkalı, delik veya çıkmış hortum\n\nKontrol adımları\n1. Soket, kablo ve hortumları kontrol ettirin\n\nDikkat\nDPF uyarısı veya güç kaybı varsa servise başvurun. Kodu silmek filtreyi temizlemez.");
        MAP.put("P2455", "DPF basınç sensörü sinyali yüksek\n\nNe anlama geliyor?\nBasınç sensöründen yüksek sinyal geliyor.\n\nOlası nedenler\n• Sensör, soket veya kablo\n• Tıkalı, delik veya çıkmış hortum\n\nKontrol adımları\n1. Soket, kablo ve hortumları kontrol ettirin\n\nDikkat\nDPF uyarısı veya güç kaybı varsa servise başvurun. Kodu silmek filtreyi temizlemez.");
        MAP.put("P2458", "DPF rejenerasyon süresi hatası\n\nNe anlama geliyor?\nRejenerasyon beklenen sürede tamamlanmıyor.\n\nOlası nedenler\n• Sık kısa mesafe kullanımı\n• Sıcaklık/basınç sensörü veya motor arızası\n\nKontrol adımları\n1. Diğer kodları giderin\n2. Rejenerasyon koşullarını serviste kontrol ettirin\n\nDikkat\nDPF uyarısı veya güç kaybı varsa servise başvurun. Kodu silmek filtreyi temizlemez.");
        MAP.put("P2459", "DPF rejenerasyonu çok sık\n\nNe anlama geliyor?\nRejenerasyon beklenenden sık yapılıyor.\n\nOlası nedenler\n• Motorun fazla kurum üretmesi\n• Sensör sorunu\n• Kısa mesafe kullanımı veya yıpranmış filtre\n\nKontrol adımları\n1. EGR, enjektör, turbo ve sensörleri kontrol ettirin\n2. Motor yağı seviyesini kontrol edin\n\nDikkat\nDPF uyarısı veya güç kaybı varsa servise başvurun. Kodu silmek filtreyi temizlemez.");
        MAP.put("P2463", "DPF kurum birikimi\n\nNe anlama geliyor?\nFiltrede fazla kurum biriktiği algılanıyor.\n\nOlası nedenler\n• Tamamlanamayan rejenerasyon\n• Sensör veya motor arızası\n\nKontrol adımları\n1. DPF rehberine bakın\n2. Kurum yükünü serviste ölçtürün\n\nDikkat\nDPF uyarısı veya güç kaybı varsa servise başvurun. Kodu silmek filtreyi temizlemez.");
    }

    static final String DPF_GUIDE = "• Bu uygulama DPF'ye komut göndermez ve zorla rejenerasyon yapmaz.\n\n• Aracınızda DPF olup olmadığını şasi numarasıyla servisten doğrulayın.\n\n• Yalnızca DPF uyarısı yanıyorsa, kullanım kılavuzundaki rejenerasyon sürüşünü uygulayın. Hız sınırlarına uyun; sürerken telefonla ilgilenmeyin.\n\n• Motor arıza lambası, güç kaybı, yağ uyarısı veya yağ seviyesinde yükselme varsa sürüşle temizlemeyi denemeyin; servise gidin.\n\n• Rejenerasyon sırasında egzoz çok ısınır. Kapalı alanda veya kuru ot, yaprak gibi yanıcı şeylerin üzerinde bekletmeyin.\n\n• Servis rejenerasyonu, neden olan arıza giderildikten sonra aracınızı destekleyen teşhis cihazıyla yapılmalıdır.\n\n• Kodu silmek kurumu veya külü temizlemez.";

    static String describe(String code) {
        String key = code == null ? "" : code.trim().toUpperCase(java.util.Locale.ROOT);
        String text = MAP.get(key);
        return text != null ? text
                : "Bu kod için henüz Türkçe açıklama yok. Üstteki özgün açıklamaya bakın ve marka servis bilgisiyle doğrulayın.";
    }
}
